// server/ai/tools/write/reservations.ts
function auditReference(doc) {
  return doc.reservationId?.trim() || doc.id;
}
function describe(doc) {
  const parts = [doc.guestName || "Unnamed guest"];
  if (doc.roomNumber) parts.push(`room ${doc.roomNumber}`);
  if (doc.reservationId) parts.push(doc.reservationId);
  return parts.join(", ");
}
async function resolveReservation(hotelId, reference) {
  const all = await listDocsUncached(hotelId, COLLECTIONS.RESERVATIONS);
  const wanted = reference.trim().toLowerCase();
  const byNumber = all.filter(
    (doc) => String(doc.reservationId ?? "").trim().toLowerCase() === wanted
  );
  if (byNumber.length === 1) return byNumber[0];
  const byName = all.filter(
    (doc) => String(doc.guestName ?? "").trim().toLowerCase().includes(wanted)
  );
  const matches = byNumber.length > 1 ? byNumber : byName;
  if (matches.length === 0) {
    throw new ToolValidationError(
      `No reservation matches '${reference}'. Try the reservation number, or the guest's name as recorded.`
    );
  }
  if (matches.length > 1) {
    const candidates = matches.slice(0, 5).map(describe).join("; ");
    throw new ToolValidationError(
      `'${reference}' matches ${matches.length} reservations: ${candidates}. Ask the user which one they mean; do not choose.`
    );
  }
  return matches[0];
}
